-    public static PersistentTasksCustomMetadata rewritePersistentTaskParams(
-        Map<String, Job> jobs,
-        Map<String, DatafeedConfig> datafeeds,
-        PersistentTasksCustomMetadata currentTasks,
-        DiscoveryNodes nodes
