-            if (originalParams.getJob() == null) {
-                Job job = jobs.get(originalParams.getJobId());
-                if (job != null) {
-                    logger.debug("updating persistent task params for job [{}]", originalParams.getJobId());
-
-                    // copy and update the job parameters
